  tag = "ResourceNotFoundException",
  categories = { "BadRequestError" },
  fields = { "Code" },
})
classes.ServiceQuotaExceededException = errors.define({
  tag = "ServiceQuotaExceededException",
  categories = { "QuotaError" },
  fields = { "Code" },
})
classes.ThrottlingException = errors.define({
  tag = "ThrottlingException",
  categories = { "ThrottlingError", "RetryableError" },
  fields = { "Code" },
})
classes.ValidationException = errors.define({
  tag = "ValidationException",
  categories = { "BadRequestError" },
  fields = { "Code" },
})

local ops = {}
for i = 1, 1 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "aws.securityhub",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "aws-api",
    prefix = "SecurityHub",
    service = "SecurityHub",
    propagate = "xray",
    response_headers = {
      { header = "x-amzn-requestid", name = "aws.request_id" },
      { header = "x-amz-request-id", name = "aws.request_id" },
      { header = "x-amzn-request-id", name = "aws.request_id" },
      { header = "x-amz-id-2", name = "aws.extended_request_id" },
    },
  },
}
